// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge as C} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    // fuzzed actor and guess hash
    function testFuzz_property(address actor, bytes32 guessHash) public {
        actor = address(uint160(bound(uint256(uint160(actor)), 0xffff + 1, type(uint160).max)));
        vm.assume(actor.code.length == 0 && actor != address(this) && actor != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && actor != 0x000000000000000000636F6e736F6c652e6c6f67 && actor != 0x4e59b44847b379578588920cA78FbF26c0B4956C && actor != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(actor != address(0));
        // fund the actor so they can pay 1 ether
        vm.deal(actor, 2 ether);

        // actor calls lockInGuess paying exactly 1 ether
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Now, the reference contract stores a future block (block.number+1), so calling
        // settle in the same block must revert. We detect revert via try/catch and assertTrue on the flag.
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: immediately after lockInGuess, calling settle in the same block MUST revert on the reference.
        // The mutant that stored block.number (current block) would allow settle to proceed (ok == true) for some inputs,
        // so this assertion will fail on that mutant for some fuzzed inputs.
        assertTrue(!ok);
    }
}
